properties.query:
let admin_events = SecurityEvent | where EventID == 4688 and NewProcessName has_any ("procdump.exe", "mimikatz.exe", "lazagne.exe", "sharpkatz.exe") | summarize admin_time=min(TimeGenerated) by SubjectUserName, Computer;
let cred_events = SecurityEvent | where EventID == 4663 and ObjectName has "lsass" | summarize cred_time=min(TimeGenerated) by SubjectUserName, Computer;
let spread_events = SecurityEvent | where EventID == 4624 and LogonType == 3 | summarize spread_time=min(TimeGenerated), host_count=dcount(Computer) by TargetUserName | where host_count > 3;
admin_events | join kind=inner cred_events on SubjectUserName, Computer | where cred_time - admin_time between (0min .. 30min)
